import fs from'node:fs';import{createTceSpellBonusEngine}from'./tce-spell-bonus-native.mjs';import{tceSpellBonusProfiles}from'../../src/data/lib/tce-spell-bonus-profiles.js';import{selectSpellSource}from'../../src/data/lib/spell-source.js';
const cases=[];for(const p of tceSpellBonusProfiles()){const drum=p.family==='rhythm',main=drum?'Bard':'Cleric',secondary=drum?'Sorcerer':'Wizard',e=createTceSpellBonusEngine({item:p.item,main,secondary});cases.push({item:p.item,magnitude:p.magnitude,main,secondary,drum,inventory:structuredClone(e.c.B.inv),casting:structuredClone(e.C.spellcasting),values:[main,secondary].map(cls=>({cls,...selectSpellSource(e.C.spellcasting,e.C.spells.find(s=>s.src===cls))}))});}fs.writeFileSync(new URL('./tce-spell-bonus-fx.json',import.meta.url),JSON.stringify({cases},null,2)+'\n');console.log('6 actual native profile numerical snapshots generated');
